INSERT INTO "usuarios" ("id", "nome", "email", "senha_hash", "perfil") VALUES
  (1, 'Ana Atendente', 'admin@helpdesk.local', crypt('admin123', gen_salt('bf', 10)), 'ATENDENTE'),
