INSERT INTO "categorias" ("id", "nome") VALUES
  (1, 'Acesso/Login'),
  (2, 'Financeiro'),
  (3, 'Bug no sistema'),
  (4, 'Dúvida'),
  (5, 'Infraestrutura');
INSERT INTO "chamados" ("id", "titulo", "descricao", "solicitante_nome", "solicitante_email", "categoria_id", "prioridade", "status", "criado_em", "atualizado_em", "resolvido_em") VALUES
  (1, 'Não consigo acessar o sistema após troca de senha', 'Troquei a senha ontem à tarde e desde então aparece a mensagem de usuário ou senha inválidos. Já tentei limpar o cache do navegador.', 'Carla Menezes', 'carla.menezes@exemplo.com', 1, 'ALTA', 'EM_ANDAMENTO', pg_temp.ha(36445), pg_temp.ha(36249), NULL),
  (2, 'Conta bloqueada por excesso de tentativas', 'Minha conta foi bloqueada depois de errar a senha três vezes. Preciso do desbloqueio para emitir os relatórios de hoje.', 'Rafael Tavares', 'rafael.tavares@exemplo.com', 1, 'MEDIA', 'ABERTO', pg_temp.ha(3782), pg_temp.ha(3782), NULL),
  (3, 'Solicito acesso ao módulo de relatórios', 'Fui transferido para o time de planejamento e preciso de permissão de leitura no módulo de relatórios gerenciais.', 'Juliana Prado', 'juliana.prado@exemplo.com', 1, 'BAIXA', 'EM_ANDAMENTO', pg_temp.ha(22062), pg_temp.ha(21998), NULL),
  (4, 'Autenticação em dois fatores não envia o código', 'O código de verificação não chega por SMS. Meu telefone cadastrado é (48) 99812-3456, confirmei que está correto.', 'Marcos Vieira', 'marcos.vieira@exemplo.com', 1, 'ALTA', 'CANCELADO', pg_temp.ha(29517), pg_temp.ha(29079), NULL),
  (5, 'Link de redefinição de senha expirado', 'Cliquei no link de redefinição recebido por e-mail e a página informa que o link expirou, mesmo tendo aberto em poucos minutos.', 'Beatriz Lacerda', 'beatriz.lacerda@exemplo.com', 1, 'MEDIA', 'FECHADO', pg_temp.ha(25289), pg_temp.ha(21803), pg_temp.ha(24305)),
  (6, 'Ninguém do time comercial consegue logar', 'Desde as 8h nenhum usuário do comercial consegue entrar no sistema. A tela fica carregando e volta para o login.', 'Thiago Antunes', 'thiago.antunes@exemplo.com', 1, 'CRITICA', 'RESOLVIDO', pg_temp.ha(5824), pg_temp.ha(5470), pg_temp.ha(5470)),
  (7, 'Alterar e-mail de login', 'Mudei de área e meu e-mail corporativo mudou. Gostaria de atualizar o e-mail usado no login.', 'Fernanda Rocha', 'fernanda.rocha@exemplo.com', 1, 'BAIXA', 'FECHADO', pg_temp.ha(69932), pg_temp.ha(67308), pg_temp.ha(69447)),
  (8, 'Sessão expira a cada poucos minutos', 'O sistema me desloga a cada cinco minutos mais ou menos, mesmo enquanto estou preenchendo formulários.', 'Lucas Moraes', 'lucas.moraes@exemplo.com', 1, 'MEDIA', 'EM_ANDAMENTO', pg_temp.ha(36788), pg_temp.ha(36579), NULL),
  (9, 'Boleto gerado com valor incorreto', 'O boleto da fatura de setembro saiu com valor diferente do contrato. O correto seria R$ 1.250,00 e saiu R$ 1.520,00.', 'Patrícia Duarte', 'patricia.duarte@exemplo.com', NULL, 'ALTA', 'ABERTO', pg_temp.ha(3976), pg_temp.ha(3976), NULL),
  (10, 'Nota fiscal não chegou por e-mail', 'A nota fiscal referente ao pagamento do mês passado não foi enviada para o e-mail financeiro da empresa.', 'André Sampaio', 'andre.sampaio@exemplo.com', 2, 'MEDIA', 'FECHADO', pg_temp.ha(21148), pg_temp.ha(16411), pg_temp.ha(18722)),
  (11, 'Dúvida sobre data de vencimento', 'Gostaria de alterar a data de vencimento das próximas faturas do dia 5 para o dia 15.', 'Camila Freitas', 'camila.freitas@exemplo.com', 2, 'BAIXA', 'RESOLVIDO', pg_temp.ha(30685), pg_temp.ha(28929), pg_temp.ha(28929)),
  (12, 'Cobrança em duplicidade no cartão', 'Fui cobrado duas vezes pela mesma assinatura neste mês. Preciso do estorno de uma das cobranças.', 'Bruno Carvalho', 'bruno.carvalho@exemplo.com', 2, 'ALTA', 'FECHADO', pg_temp.ha(34481), pg_temp.ha(33010), pg_temp.ha(33099)),
  (13, 'Relatório de pagamentos com totais divergentes', 'O total exibido no relatório de pagamentos não bate com a soma das linhas exportadas para planilha.', 'Larissa Pires', 'larissa.pires@exemplo.com', 2, 'MEDIA', 'RESOLVIDO', pg_temp.ha(40820), pg_temp.ha(38352), pg_temp.ha(38352)),
  (14, 'Atualizar dados de faturamento', 'Precisamos atualizar a razão social e o endereço que aparecem nas notas fiscais emitidas.', 'Diego Fontes', 'diego.fontes@exemplo.com', 2, 'BAIXA', 'RESOLVIDO', pg_temp.ha(57674), pg_temp.ha(56808), pg_temp.ha(56808)),
  (15, 'Pagamento confirmado mas fatura segue em aberto', 'Paguei o boleto na segunda-feira e a fatura continua aparecendo como em aberto no portal.', 'Aline Barbosa', 'aline.barbosa@exemplo.com', 2, 'MEDIA', 'EM_ANDAMENTO', pg_temp.ha(5412), pg_temp.ha(5299), NULL),
  (16, 'Integração bancária parou de importar extratos', 'A conciliação automática não importa extratos desde ontem. O fechamento do mês depende disso.', 'Gustavo Neves', 'gustavo.neves@exemplo.com', 2, 'CRITICA', 'FECHADO', pg_temp.ha(28370), pg_temp.ha(24913), pg_temp.ha(25996)),
  (17, 'Erro 500 ao salvar cadastro de cliente', 'Ao clicar em salvar no cadastro de clientes aparece erro 500. Acontece com qualquer cliente novo.', 'Renata Coelho', 'renata.coelho@exemplo.com', 3, 'ALTA', 'CANCELADO', pg_temp.ha(2407), pg_temp.ha(2282), NULL),
  (18, 'Filtro por data não traz resultados', 'Na tela de pedidos, ao filtrar por período, a lista fica vazia mesmo havendo pedidos nas datas informadas.', 'Felipe Arruda', 'felipe.arruda@exemplo.com', 3, 'MEDIA', 'FECHADO', pg_temp.ha(56885), pg_temp.ha(53205), pg_temp.ha(54817)),
  (19, 'Texto cortado no botão de exportar', 'No celular o texto do botão exportar fica cortado e não dá para ler a opção.', 'Mariana Teles', 'mariana.teles@exemplo.com', 3, 'BAIXA', 'EM_ANDAMENTO', pg_temp.ha(37862), pg_temp.ha(37683), NULL),
  (20, 'Pedidos duplicados ao confirmar compra', 'Clientes relatam que ao confirmar a compra o pedido é criado duas vezes e o estoque baixa em dobro.', 'Rodrigo Brandão', 'rodrigo.brandao@exemplo.com', 3, 'CRITICA', 'RESOLVIDO', pg_temp.ha(80889), pg_temp.ha(76050), pg_temp.ha(76050)),
  (21, 'Upload de anexo falha com arquivos PDF', 'Ao anexar arquivos PDF acima de 2 MB o upload fica em 99% e depois mostra erro genérico.', 'Carla Menezes', 'carla.menezes@exemplo.com', 3, 'MEDIA', 'RESOLVIDO', pg_temp.ha(57243), pg_temp.ha(51857), pg_temp.ha(51857)),
  (22, 'Relatório de vendas trava o navegador', 'Ao gerar o relatório de vendas do trimestre o navegador congela e precisa ser fechado.', 'Rafael Tavares', 'rafael.tavares@exemplo.com', 3, 'ALTA', 'FECHADO', pg_temp.ha(38499), pg_temp.ha(30947), pg_temp.ha(32293)),
  (23, 'Ordenação da tabela de produtos invertida', 'Ao ordenar produtos por nome a lista vem de Z para A mesmo selecionando a ordem crescente.', 'Juliana Prado', 'juliana.prado@exemplo.com', 3, 'BAIXA', 'CANCELADO', pg_temp.ha(2050), pg_temp.ha(1551), NULL),
  (24, 'Notificações duplicadas no painel', 'Cada aviso aparece duas vezes no sino de notificações do painel principal.', 'Marcos Vieira', 'marcos.vieira@exemplo.com', 3, 'MEDIA', 'FECHADO', pg_temp.ha(21681), pg_temp.ha(19338), pg_temp.ha(20398)),
  (25, 'Como exportar a lista de clientes', 'Gostaria de saber se é possível exportar a lista de clientes em CSV e onde fica essa opção.', 'Beatriz Lacerda', 'beatriz.lacerda@exemplo.com', 4, 'BAIXA', 'RESOLVIDO', pg_temp.ha(5345), pg_temp.ha(4150), pg_temp.ha(4150)),
  (26, 'Diferença entre perfis de usuário', 'Qual a diferença entre o perfil gestor e o perfil analista? Preciso definir o perfil de um novo colaborador.', 'Thiago Antunes', 'thiago.antunes@exemplo.com', 4, 'BAIXA', 'RESOLVIDO', pg_temp.ha(24694), pg_temp.ha(24057), pg_temp.ha(24057)),
  (27, 'Como configurar aprovação em duas etapas', 'Queremos que pedidos acima de determinado valor passem por duas aprovações. Isso é configurável?', 'Fernanda Rocha', 'fernanda.rocha@exemplo.com', 4, 'MEDIA', 'CANCELADO', pg_temp.ha(4769), pg_temp.ha(4645), NULL),
  (28, 'Onde vejo o histórico de alterações', 'Existe algum lugar onde consigo ver quem alterou o cadastro de um fornecedor?', 'Lucas Moraes', 'lucas.moraes@exemplo.com', 4, 'BAIXA', 'FECHADO', pg_temp.ha(62232), pg_temp.ha(58940), pg_temp.ha(61297)),
  (29, 'Limite de usuários do plano', 'Quantos usuários simultâneos o nosso plano atual permite?', 'Patrícia Duarte', 'patricia.duarte@exemplo.com', NULL, 'BAIXA', 'ABERTO', pg_temp.ha(7071), pg_temp.ha(7071), NULL),
  (30, 'Integração com planilhas', 'É possível integrar os relatórios do sistema com planilhas online para atualização automática?', 'André Sampaio', 'andre.sampaio@exemplo.com', 4, 'MEDIA', 'ABERTO', pg_temp.ha(3471), pg_temp.ha(3471), NULL),
  (31, 'Treinamento para novos colaboradores', 'Vocês oferecem material de treinamento para novos usuários do sistema? Temos três pessoas começando.', 'Camila Freitas', 'camila.freitas@exemplo.com', 4, 'BAIXA', 'CANCELADO', pg_temp.ha(16954), pg_temp.ha(16758), NULL),
  (32, 'Personalizar campos do cadastro', 'Consigo adicionar um campo personalizado no cadastro de produtos para o código interno?', 'Bruno Carvalho', 'bruno.carvalho@exemplo.com', 4, 'BAIXA', 'FECHADO', pg_temp.ha(58284), pg_temp.ha(55777), pg_temp.ha(56853)),
  (33, 'Servidor de arquivos fora do ar', 'O servidor de arquivos compartilhados não responde desde as 7h. Nenhum setor consegue abrir documentos.', 'Larissa Pires', 'larissa.pires@exemplo.com', 5, 'CRITICA', 'ABERTO', pg_temp.ha(3674), pg_temp.ha(3674), NULL),
  (34, 'VPN desconectando com frequência', 'A VPN cai a cada 10 minutos para quem trabalha remoto, interrompendo chamadas e acesso aos sistemas.', 'Diego Fontes', 'diego.fontes@exemplo.com', NULL, 'ALTA', 'ABERTO', pg_temp.ha(417), pg_temp.ha(417), NULL),
  (35, 'Impressora do segundo andar não imprime', 'A impressora do segundo andar recebe os trabalhos mas não imprime. O painel não mostra erro.', 'Aline Barbosa', 'aline.barbosa@exemplo.com', 5, 'MEDIA', 'EM_ANDAMENTO', pg_temp.ha(34824), pg_temp.ha(34712), NULL),
  (36, 'Lentidão geral na rede da filial', 'A filial está com lentidão para acessar qualquer sistema desde a manhã. Testes de velocidade mostram queda grande.', 'Gustavo Neves', 'gustavo.neves@exemplo.com', 5, 'ALTA', 'EM_ANDAMENTO', pg_temp.ha(24094), pg_temp.ha(23898), NULL),
  (37, 'Solicitação de monitor adicional', 'Gostaria de solicitar um segundo monitor para a estação de trabalho do time de análise.', 'Renata Coelho', 'renata.coelho@exemplo.com', 5, 'BAIXA', 'EM_ANDAMENTO', pg_temp.ha(1550), pg_temp.ha(1407), NULL),
  (38, 'Certificado SSL do portal perto de expirar', 'O navegador mostra aviso de que o certificado do portal interno expira em cinco dias.', 'Felipe Arruda', 'felipe.arruda@exemplo.com', 5, 'MEDIA', 'RESOLVIDO', pg_temp.ha(43683), pg_temp.ha(42237), pg_temp.ha(42237)),
  (39, 'Backup noturno falhou', 'O relatório do backup indica falha na rotina noturna das duas últimas noites.', 'Mariana Teles', 'mariana.teles@exemplo.com', 5, 'ALTA', 'ABERTO', pg_temp.ha(11127), pg_temp.ha(11127), NULL),
  (40, 'Wi-Fi da sala de reuniões instável', 'A rede sem fio da sala de reuniões principal cai durante videochamadas.', 'Rodrigo Brandão', 'rodrigo.brandao@exemplo.com', 5, 'MEDIA', 'ABERTO', pg_temp.ha(4730), pg_temp.ha(4730), NULL);
