INSERT INTO "comentarios" ("chamado_id", "autor", "texto", "criado_em") VALUES
  (1, 'Ana Atendente', 'Estamos analisando o caso e retornamos assim que tivermos novidades.', pg_temp.ha(36343)),
  (1, 'Carla Menezes', 'Obrigado pelo retorno, fico no aguardo.', pg_temp.ha(36256)),
  (3, 'Ana Atendente', 'Estamos analisando o caso e retornamos assim que tivermos novidades.', pg_temp.ha(22014)),
  (5, 'Ana Atendente', 'Estamos analisando o caso e retornamos assim que tivermos novidades.', pg_temp.ha(25204)),
