  (3, 5, 'MEDIA', 'Solicito acesso ao módulo de relatórios. Fui transferido para o time de planejamento e preciso de permissão de leitura no módulo de relatórios gerenciais.', 'Olá! Recebemos o relato sobre a infraestrutura. A equipe de operações já está analisando e manteremos você atualizado.', 0.61, 'seed', 'triagem-v1', 'REJEITADA', NULL, 1, 985, 446, 253, 'Ana Atendente', pg_temp.ha(22022), pg_temp.ha(22061), pg_temp.ha(22061)),
