-- Dados iniciais (fictícios): usuários padrão, categorias e 40 chamados com histórico, comentários e triagens.
-- As datas são relativas ao momento da migration para manter o dashboard sempre com dados recentes.
CREATE FUNCTION pg_temp.ha(minutos integer) RETURNS timestamp AS $$ SELECT (now() AT TIME ZONE 'utc') - make_interval(mins => minutos) $$ LANGUAGE sql;







-- Ajusta as sequences porque os IDs foram informados explicitamente.
SELECT setval(pg_get_serial_sequence('"usuarios"', 'id'), (SELECT MAX("id") FROM "usuarios"));
SELECT setval(pg_get_serial_sequence('"categorias"', 'id'), (SELECT MAX("id") FROM "categorias"));
SELECT setval(pg_get_serial_sequence('"chamados"', 'id'), (SELECT MAX("id") FROM "chamados"));
